<?php
$error=null;$doctor=doctor_for_current_user();$doctorId=has_role('Doctor')?(int)($doctor['doctor_id']??0):(int)($_GET['doctor_id']??$_POST['doctor_id']??0);
if(request_method('POST')){try{verify_csrf();$action=post_string('action');$target=(int)($_POST['doctor_id']??0);if(has_role('Doctor')&&$target!==$doctorId)throw new RuntimeException('You can only manage your own schedule.');if($target<1||(int)query_value('SELECT COUNT(*) FROM doctors WHERE doctor_id=?',[$target])===0)throw new RuntimeException('Select a valid doctor.');if($action==='create'){$day=(int)($_POST['day_of_week']??-1);$start=post_string('start_time');$end=post_string('end_time');$duration=max(5,min(240,(int)($_POST['slot_duration']??15)));$max=max(1,min(200,(int)($_POST['maximum_patients']??20)));if($day<0||$day>6||!preg_match('/^\d{2}:\d{2}$/',$start)||!preg_match('/^\d{2}:\d{2}$/',$end)||$start>=$end)throw new RuntimeException('Enter a valid doctor, day and time range.');$availableMinutes=(int)((strtotime('1970-01-01 '.$end)-strtotime('1970-01-01 '.$start))/60);$availableSlots=intdiv($availableMinutes,$duration);if($availableSlots<1)throw new RuntimeException('The time range must contain at least one complete slot.');$max=min($max,$availableSlots);$stmt=db()->prepare('SELECT COUNT(*) FROM doctor_schedules WHERE doctor_id=? AND day_of_week=? AND status=\'Active\' AND NOT(end_time<=? OR start_time>=?)');$stmt->execute([$target,$day,$start,$end]);if((int)$stmt->fetchColumn()>0)throw new RuntimeException('This schedule overlaps an existing active schedule.');db()->prepare('INSERT INTO doctor_schedules (doctor_id,day_of_week,start_time,end_time,slot_duration,maximum_patients,room_number,status) VALUES (?,?,?,?,?,?,?,\'Active\')')->execute([$target,$day,$start,$end,$duration,$max,nullable(post_string('room_number'))]);$id=(int)db()->lastInsertId();log_action('CREATE','doctor_schedules',$id);flash('schedule','Schedule added.','success');redirect_to('schedules',['doctor_id'=>$target]);}if($action==='toggle'){$id=(int)($_POST['schedule_id']??0);$stmt=db()->prepare('SELECT * FROM doctor_schedules WHERE schedule_id=? AND doctor_id=?');$stmt->execute([$id,$target]);$schedule=$stmt->fetch();if(!$schedule)throw new RuntimeException('Schedule not found.');if($schedule['status']!=='Active'){$overlap=db()->prepare("SELECT COUNT(*) FROM doctor_schedules WHERE doctor_id=? AND day_of_week=? AND schedule_id<>? AND status='Active' AND NOT(end_time<=? OR start_time>=?)");$overlap->execute([$target,$schedule['day_of_week'],$id,$schedule['start_time'],$schedule['end_time']]);if((int)$overlap->fetchColumn()>0)throw new RuntimeException('This schedule overlaps another active schedule and cannot be enabled.');}$newStatus=$schedule['status']==='Active'?'Inactive':'Active';db()->prepare('UPDATE doctor_schedules SET status=? WHERE schedule_id=? AND doctor_id=?')->execute([$newStatus,$id,$target]);log_action('TOGGLE_STATUS','doctor_schedules',$id,['status'=>$schedule['status']],['status'=>$newStatus]);flash('schedule','Schedule status changed.','success');redirect_to('schedules',['doctor_id'=>$target]);}if($action==='exception'){$date=post_string('exception_date');$type=post_string('exception_type');$alternativeStart=post_string('alternative_start_time');$alternativeEnd=post_string('alternative_end_time');if(!validate_date($date)||$date<date('Y-m-d'))throw new RuntimeException('Choose a valid current or future date.');if(!in_array($type,['Unavailable','Alternative Hours'],true))throw new RuntimeException('Choose a valid exception type.');if($type==='Alternative Hours'&&(!preg_match('/^\d{2}:\d{2}$/',$alternativeStart)||!preg_match('/^\d{2}:\d{2}$/',$alternativeEnd)||$alternativeStart>=$alternativeEnd))throw new RuntimeException('Alternative hours require a valid start and end time.');if($type==='Unavailable'){$alternativeStart='';$alternativeEnd='';}$stmt=db()->prepare('INSERT INTO schedule_exceptions (doctor_id,exception_date,exception_type,reason,alternative_start_time,alternative_end_time) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE exception_type=VALUES(exception_type),reason=VALUES(reason),alternative_start_time=VALUES(alternative_start_time),alternative_end_time=VALUES(alternative_end_time)');$stmt->execute([$target,$date,$type,nullable(post_string('reason')),nullable($alternativeStart),nullable($alternativeEnd)]);log_action('UPSERT','schedule_exceptions',$target.'-'.$date);flash('schedule','Schedule exception saved.','success');redirect_to('schedules',['doctor_id'=>$target]);}}catch(Throwable $e){$error=$e->getMessage();}}
$doctors=has_role('Admin')?db()->query("SELECT d.doctor_id,u.full_name FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.status='Active' ORDER BY u.full_name")->fetchAll():[];if($doctorId<1&&$doctors)$doctorId=(int)$doctors[0]['doctor_id'];$doctorName=$doctorId?(string)query_value('SELECT u.full_name FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.doctor_id=?',[$doctorId]):'';$stmt=db()->prepare('SELECT * FROM doctor_schedules WHERE doctor_id=? ORDER BY day_of_week,start_time');$stmt->execute([$doctorId]);$rows=$stmt->fetchAll();$stmt=db()->prepare('SELECT * FROM schedule_exceptions WHERE doctor_id=? AND exception_date>=CURDATE() ORDER BY exception_date LIMIT 20');$stmt->execute([$doctorId]);$exceptions=$stmt->fetchAll();
?>
<div class="page-header"><div><h2>Doctor schedules</h2><p>Recurring availability and one-day exceptions.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if(has_role('Admin')):?><div class="card mb-2"><form method="get" class="actions"><input type="hidden" name="page" value="schedules"><select class="select" style="max-width:320px" name="doctor_id" onchange="this.form.submit()"><?php foreach($doctors as $d):?><option value="<?=$d['doctor_id']?>" <?=$doctorId===$d['doctor_id']?'selected':''?>><?=e($d['full_name'])?></option><?php endforeach;?></select></form></div><?php endif;?>
<div class="grid grid-3"><div class="card" style="grid-column:span 2"><div class="card-header"><div><h3><?=e($doctorName?:'No doctor selected')?></h3><p>Weekly active and inactive schedules.</p></div></div><?php if($rows):?><div class="table-wrap"><table class="data-table"><thead><tr><th>Day</th><th>Time</th><th>Slot</th><th>Max patients</th><th>Room</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="table-title"><?=day_name((int)$r['day_of_week'])?></td><td><?=format_time($r['start_time'])?> – <?=format_time($r['end_time'])?></td><td><?=$r['slot_duration']?> min</td><td><?=$r['maximum_patients']?></td><td><?=e($r['room_number']??'—')?></td><td><span class="badge badge-<?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><input type="hidden" name="schedule_id" value="<?=$r['schedule_id']?>"><button class="btn btn-warning btn-sm"><?=$r['status']==='Active'?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><p>No schedule has been added.</p></div><?php endif;?><div class="divider"></div><h3>Add recurring schedule</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><div class="form-grid form-grid-3"><div class="field"><label>Day</label><select class="select" name="day_of_week"><?php for($i=0;$i<7;$i++):?><option value="<?=$i?>"><?=day_name($i)?></option><?php endfor;?></select></div><div class="field"><label>Start time</label><input class="input" type="time" name="start_time" value="09:00" required></div><div class="field"><label>End time</label><input class="input" type="time" name="end_time" value="13:00" required></div><div class="field"><label>Slot minutes</label><input class="input" type="number" min="5" name="slot_duration" value="15"></div><div class="field"><label>Maximum patients</label><input class="input" type="number" min="1" name="maximum_patients" value="16"></div><div class="field"><label>Room</label><input class="input" name="room_number"></div></div><button class="btn btn-primary">Add schedule</button></form></div>
<div class="card"><div class="card-header"><div><h3>Date exceptions</h3><p>Mark leave or special hours.</p></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="exception"><input type="hidden" name="doctor_id" value="<?=$doctorId?>"><div class="field"><label>Date</label><input class="input" type="date" min="<?=date('Y-m-d')?>" name="exception_date" required></div><div class="field"><label>Type</label><select class="select" name="exception_type"><option>Unavailable</option><option>Alternative Hours</option></select></div><div class="form-grid"><div class="field"><label>Alternative start</label><input class="input" type="time" name="alternative_start_time"></div><div class="field"><label>Alternative end</label><input class="input" type="time" name="alternative_end_time"></div></div><div class="field"><label>Reason</label><input class="input" name="reason"></div><button class="btn btn-light">Save exception</button></form><div class="divider"></div><?php foreach($exceptions as $x):?><div style="padding:9px 0;border-bottom:1px solid var(--line)"><strong><?=format_date($x['exception_date'])?></strong><div class="table-subtitle"><?=e($x['exception_type'])?> · <?=e($x['reason']??'No reason')?></div></div><?php endforeach;?></div></div>
